import pytest
import requests
from jsonschema import validate

@pytest.fixture
def valid_username():
    return "user1"

@pytest.fixture
def invalid_username():
    return "nonexistentuser"

def test_get_user_valid_username(base_url, valid_username):
    """
    Test fetching user details with a valid username.
    """
    url = f"{base_url}/user/{valid_username}"
    response = requests.get(url)
    assert response.status_code == 200

    response_json = response.json()
    user_schema = {
        "type": "object",
        "properties": {
            "id": {"type": "integer"},
            "username": {"type": "string"},
            "firstName": {"type": "string"},
            "lastName": {"type": "string"},
            "email": {"type": "string"},
            "password": {"type": "string"},
            "phone": {"type": "string"},
            "userStatus": {"type": "integer"}
        },
        "required": ["id", "username", "firstName", "lastName", "email", "userStatus"]
    }
    validate(instance=response_json, schema=user_schema)


def test_get_user_invalid_username(base_url, invalid_username):
    """
    Test fetching user details with an invalid username.
    """
    url = f"{base_url}/user/{invalid_username}"
    response = requests.get(url)
    assert response.status_code == 404
    assert "User not found" in response.text


@pytest.mark.parametrize("missing_auth, expected_status", [
    (None, 401),
    ("wrong_token", 401)
])
def test_get_user_authentication(base_url, valid_username, missing_auth, auth_token, expected_status):
    """
    Test fetching user details with missing/invalid authentication.
    """
    url = f"{base_url}/user/{valid_username}"
    headers = {"Authorization": missing_auth or auth_token}
    response = requests.get(url, headers=headers)
    assert response.status_code == expected_status


def test_invalid_http_method(base_url, valid_username):
    """
    Test invalid HTTP method on user endpoint (e.g., POST instead of GET).
    """
    url = f"{base_url}/user/{valid_username}"
    response = requests.post(url, json={"username": valid_username})
    assert response.status_code == 405


